import React from 'react';
import Header from '../Header';
import './Itempage.css';
import Footer from '../Footer';
import saree1 from './saree1.jpg';
import saree2 from './saree2.jpg';
import saree3 from './saree3.jpg';
import saree4 from './saree4.jpg';

function Itempage() {
    return (
        <div className='Itempage'>
            <Header/>
            <div className='Itempagelayout'>
                <h1>Create a Flex Container</h1>
                <div class="flex-container1">
                    <div className='Saree1'>
                        <img src={saree1}/>
                    </div>
                    <div className='Saree2'>
                        <img src={saree2}/>
                    </div>
                    <div className='Saree3'>
                        <img src={saree3}/>
                    </div>  
                </div>
                <div className='flexbox2'>
                    <img src={saree4}/>            
                </div>
                <Footer/>
            </div>
        </div>
    );
}

export default Itempage;
